actions.script:
const out = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectEstimate').parameters({workEffortId: workEffortId || '',
    depth: depth ? Number(depth) : 2}).call() || {}
const refused = ec.message.hasError() ? ec.message.getErrorsString() : ''
ec.message.clearErrors()
const enc = (text) => String(text == null ? '' : text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
printHtml = out.estimateHtml || ('<p>' + enc(refused || ec.l10n.localize('The estimate is not available')) + '</p>')
printUrl = '/apps/Projects/Projects/EstimatePrint?renderMode=html-print&workEffortId=' + encodeURIComponent(workEffortId || '') + (depth ? '&depth=' + encodeURIComponent(depth) : '')
